contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(bytes32 identifier, uint256 time, bytes calldata ancillaryData) public {
        address oa = c.optimisticAsserter();
        bool reverted;
        if (oa != address(this)) {
            try c.requestPrice(identifier, time, ancillaryData) { reverted = false; }
            catch { reverted = true; }
            assert(reverted);
        } else {
            c.requestPrice(identifier, time, ancillaryData);
            // When authorized, the call succeeds and does not revert.
            assert(address(c).code.length > 0);
        }
    }

    receive() external payable {}
}

