contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(bytes32 assertionId, bytes32 identifier, uint256 time, bytes calldata ancillaryData) public {
        // As a fresh deployment, this contract is not the optimistic asserter,
        // so both restricted callbacks and requestPrice must revert.
        bool disputedReverted;
        try c.assertionDisputedCallback(assertionId) { disputedReverted = false; }
        catch { disputedReverted = true; }

        bool resolvedReverted;
        try c.assertionResolvedCallback(assertionId, true) { resolvedReverted = false; }
        catch { resolvedReverted = true; }

        bool requestReverted;
        try c.requestPrice(identifier, time, ancillaryData) { requestReverted = false; }
        catch { requestReverted = true; }

        assert(disputedReverted && resolvedReverted && requestReverted);
    }

    receive() external payable {}
}

