contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(bytes32 identifier, uint256 time, bytes memory ancillaryData, bytes32 assertionId) public payable {
        require(true);

        // Only the optimistic asserter may call requestPrice; we are not, so it must revert.
        bool rpReverted;
        try c.requestPrice(identifier, time, ancillaryData) { rpReverted = false; } catch { rpReverted = true; }
        assert(rpReverted);

        // Same for the callback recipients.
        bool rcReverted;
        try c.assertionResolvedCallback(assertionId, true) { rcReverted = false; } catch { rcReverted = true; }
        assert(rcReverted);

        bool rdReverted;
        try c.assertionDisputedCallback(assertionId) { rdReverted = false; } catch { rdReverted = true; }
        assert(rdReverted);

        // View functions expose the default permissive policy and an unset price.
        assert(c.getPrice(identifier, time, ancillaryData) == 0);
        assert(c.isDisputeAllowed(assertionId, address(this)));
        C.AssertionPolicy memory p = c.getAssertionPolicy(assertionId);
        assert(!p.blockAssertion && !p.arbitrateViaEscalationManager && !p.discardOracle && !p.validateDisputers);
    }
    receive() external payable {}
}

