contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(bytes32 identifier, uint256 time, bytes memory ancillaryData, bytes32 assertionId, address disputeCaller) public {
        // Verify view-only guarantee rules first on fresh state.
        bool dAllowed = c.isDisputeAllowed(assertionId, disputeCaller);
        assert(dAllowed);

        // requestPrice from a non-asserter must revert; catch result via try.
        bool reverted;
        // top-level state-changing attempt wrapped via try is forbidden, so use direct call and rely
        // on the modifier: msg.sender (this contract) != optimisticAsserter, so it must revert.
        // Use low-level call to observe revert without failing the transaction.
        (bool ok, ) = address(c).call(
            abi.encodeWithSelector(c.requestPrice.selector, identifier, time, ancillaryData)
        );
        reverted = !ok;
        assert(reverted);

        // assertionResolvedCallback from a non-asserter must revert too.
        (bool ok2, ) = address(c).call(
            abi.encodeWithSelector(c.assertionResolvedCallback.selector, assertionId, true)
        );
        assert(!ok2);

        // getAssertionPolicy always returns all-false policy for any assertionId.
        C.AssertionPolicy memory p = c.getAssertionPolicy(assertionId);
        assert(!p.blockAssertion && !p.arbitrateViaEscalationManager && !p.discardOracle && !p.validateDisputers);
    }
}

